-- Mirror of the updater's Postgres schema: its Flyway migrations, concatenated in
-- version order. GENERATED by docker/generate-schema.sh; do not edit by hand.
-- Updater migrations as of commit 6ec308d 2026-11-14.
--
-- Used by the seed mode only (docker/postgres/init/01-seed-data.sh). A full load
-- starts from an empty database instead, so Flyway can build and record the schema.

-- ===== V1__baseline.sql =====

-- Baseline: the schema Hibernate (ddl-auto=update) generated from the entities as of
-- 2026-10-06, taken from pg_dump on Postgres 16. Databases created before Flyway are
-- identical to this and are adopted as V1 via spring.flyway.baseline-on-migrate.
-- Free-text and list columns are text / text[] on purpose (real values exceed 255
-- chars); UpdaterComponentApplicationIT.freeTextColumnsAreNotLengthLimited guards this.

CREATE TABLE source_version (
    feed_id         varchar(255) NOT NULL,
    content_hash    varchar(255),
    last_checked_at timestamp(6) with time zone,
    last_updated_at timestamp(6) with time zone,
    CONSTRAINT source_version_pkey PRIMARY KEY (feed_id)
);

-- JMdict
CREATE TABLE vocab_entry (
    ent_seq bigint NOT NULL,
    common  boolean,
    CONSTRAINT vocab_entry_pkey PRIMARY KEY (ent_seq)
);

CREATE TABLE reading (
    id      bigint GENERATED BY DEFAULT AS IDENTITY,
    kanji   boolean,
    text    varchar(255) NOT NULL,
    ent_seq bigint,
    CONSTRAINT reading_pkey PRIMARY KEY (id),
    CONSTRAINT fkpen0rh63p9s9d7w6sip9t5yru FOREIGN KEY (ent_seq) REFERENCES vocab_entry (ent_seq)
);

CREATE TABLE sense (
    id      bigint GENERATED BY DEFAULT AS IDENTITY,
    ent_seq bigint,
    CONSTRAINT sense_pkey PRIMARY KEY (id),
    CONSTRAINT fkalx3bp5h8g9jvlt47s7yyn67g FOREIGN KEY (ent_seq) REFERENCES vocab_entry (ent_seq)
);

CREATE TABLE sense_gloss (
    sense_id bigint NOT NULL,
    gloss    text,
    CONSTRAINT fkh8nqj0nur4ufh2oang6qv9gkh FOREIGN KEY (sense_id) REFERENCES sense (id)
);

CREATE TABLE sense_misc (
    sense_id bigint NOT NULL,
    misc     varchar(255),
    CONSTRAINT fkd834rt5icwkybs48hs40w1eoq FOREIGN KEY (sense_id) REFERENCES sense (id)
);

CREATE TABLE sense_pos (
    sense_id bigint NOT NULL,
    pos      varchar(255),
    CONSTRAINT fklj64f642xrw890puu5wb7tc5q FOREIGN KEY (sense_id) REFERENCES sense (id)
);

-- JMnedict
CREATE TABLE name_entry (
    ent_seq      bigint NOT NULL,
    kanji        text[],
    name_types   text[],
    readings     text[],
    translations text[],
    CONSTRAINT name_entry_pkey PRIMARY KEY (ent_seq)
);

-- Kanji (KanjiDic2 / RADKFILE / KanjiVG)
CREATE TABLE kanji (
    "character"       varchar(255) NOT NULL,
    classical_radical integer,
    codepoint         varchar(255),
    frequency         integer,
    grade             integer,
    jlpt              integer,
    joyo              boolean,
    kunyomi           text[],
    meanings          text[],
    nanori            text[],
    onyomi            text[],
    stroke_count      integer,
    stroke_paths      text[],
    CONSTRAINT kanji_pkey PRIMARY KEY ("character")
);

CREATE TABLE radical (
    "character"  varchar(255) NOT NULL,
    stroke_count integer,
    CONSTRAINT radical_pkey PRIMARY KEY ("character")
);

CREATE TABLE kanji_radical (
    kanji   varchar(255) NOT NULL,
    radical varchar(255) NOT NULL,
    CONSTRAINT kanji_radical_pkey PRIMARY KEY (kanji, radical),
    CONSTRAINT fk39amf2uckytgcqvyd8qcppgdg FOREIGN KEY (kanji) REFERENCES kanji ("character"),
    CONSTRAINT fkihyxqgp0702btf0uw5rpfolwj FOREIGN KEY (radical) REFERENCES radical ("character")
);

-- Tatoeba
CREATE TABLE example_sentence (
    id          bigint NOT NULL,
    english     text,
    index_words text,
    japanese    text NOT NULL,
    source      varchar(255),
    CONSTRAINT example_sentence_pkey PRIMARY KEY (id)
);

-- ===== V2__retired_at.sql =====

-- Entries whose key disappears from a changed upstream file are retired, not deleted:
-- the row (and its children) stays so ids stored elsewhere keep resolving, and is
-- marked here. Readers must filter "retired_at IS NULL".
-- See docs/adr/0001-retire-in-postgres-delete-from-search.md.
ALTER TABLE vocab_entry      ADD COLUMN retired_at timestamp(6) with time zone;
ALTER TABLE name_entry       ADD COLUMN retired_at timestamp(6) with time zone;
ALTER TABLE example_sentence ADD COLUMN retired_at timestamp(6) with time zone;
ALTER TABLE kanji            ADD COLUMN retired_at timestamp(6) with time zone;

-- ===== V3__index_foreign_keys.sql =====

-- Postgres doesn't index foreign-key columns by itself. Without these, updating an existing
-- JMdict entry (load its readings/senses, delete the replaced ones) full-scans 250k-500k-row
-- tables for every entry: the first real changed-file run managed ~25 entries/s.
-- UpdaterComponentApplicationIT.everyForeignKeyColumnIsIndexed guards new foreign keys.
CREATE INDEX reading_ent_seq_idx        ON reading (ent_seq);
CREATE INDEX sense_ent_seq_idx          ON sense (ent_seq);
CREATE INDEX sense_gloss_sense_id_idx   ON sense_gloss (sense_id);
CREATE INDEX sense_pos_sense_id_idx     ON sense_pos (sense_id);
CREATE INDEX sense_misc_sense_id_idx    ON sense_misc (sense_id);
CREATE INDEX kanji_radical_radical_idx  ON kanji_radical (radical);

-- ===== V4__sense_list_order.sql =====

-- Keep the JMdict order of a sense's glosses, parts of speech and misc tags (the first
-- gloss is the most important one). Each list gets a 0-based order column, which with
-- sense_id is the table's primary key. The dictionary service reads these exact names
-- (gloss_order, pos_order, misc_order). Sense maps them with @OrderColumn.
--
-- Existing rows have no recorded order, and none can be rebuilt from the table, so they
-- are deleted, and the jmdict feed's version row is removed: the next run sees the file
-- as changed and re-imports every entry, writing the order. Until that run, senses have
-- no glosses or tags (decided 2026-11-14: drop and re-import, no order guessing).

DELETE FROM sense_gloss;
DELETE FROM sense_pos;
DELETE FROM sense_misc;
DELETE FROM source_version WHERE feed_id = 'jmdict';

ALTER TABLE sense_gloss ADD COLUMN gloss_order integer NOT NULL CHECK (gloss_order >= 0);
ALTER TABLE sense_pos   ADD COLUMN pos_order   integer NOT NULL CHECK (pos_order >= 0);
ALTER TABLE sense_misc  ADD COLUMN misc_order  integer NOT NULL CHECK (misc_order >= 0);

ALTER TABLE sense_gloss ADD CONSTRAINT sense_gloss_pkey PRIMARY KEY (sense_id, gloss_order);
ALTER TABLE sense_pos   ADD CONSTRAINT sense_pos_pkey   PRIMARY KEY (sense_id, pos_order);
ALTER TABLE sense_misc  ADD CONSTRAINT sense_misc_pkey  PRIMARY KEY (sense_id, misc_order);

-- The primary keys start with sense_id, so they index the foreign key (V3's guard,
-- UpdaterComponentApplicationIT.everyForeignKeyColumnIsIndexed, accepts them).
DROP INDEX sense_gloss_sense_id_idx;
DROP INDEX sense_pos_sense_id_idx;
DROP INDEX sense_misc_sense_id_idx;
